-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.creature_stock(p_world uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare want int; placed int := 0; tries int := 0; size int; gx int; gy int; got text;
begin
  select w.size into size from world w where w.id = p_world;
  -- What is out of its season is taken off before anything is counted (`wild_out_of_season`).
  perform wild_out_of_season(p_world, 0, 0, size, size);
  -- And what has had its span (`wild_turnover`).
  perform wild_turnover(p_world, 0, 0, size, size);
  want := creature_target(p_world) - (select count(*) from creature where world_id = p_world and mode = 'wild');
  while placed < want and tries < want * 40 loop
    tries := tries + 1;
    gx := floor(random() * size)::int;
    gy := floor(random() * size)::int;
    if not creature_tile_ok(p_world, gx, gy) then continue; end if;
    if centre_height(p_world, gx, gy) < 2 or on_deed(p_world, gx, gy) then continue; end if;
    got := pick_wild(p_world, gx, gy);
    if got is null or not suits(p_world, got, gx, gy) then continue; end if;
    -- Born at some point in the past, so the country is not all yearlings.
    -- And now and then, of a kind that evolves, already past its first stage (`wild_stage_put`).
    -- And now and then in a wild form (`wild_form_put`).
    perform wild_form_put(p_world, wild_stage_put(p_world, creature_spawn(p_world, got, gx + 0.5, gy + 0.5, 'wild',
      now() - make_interval(secs => random() * old_at() * 1.6))));
    placed := placed + 1;
  end loop;
  return placed;
end $function$
